import { useContext } from 'react'
import { AvailableColumnsContext, type AvailableColumnsData } from './available-columns-provider'

export type UseAvailableColumnsReturn = AvailableColumnsData

export const useAvailableColumns = (): UseAvailableColumnsReturn => {
  const context = useContext(AvailableColumnsContext)

  if (context === undefined) {
    throw new Error('useAvailableColumns must be used within a AvailableColumnsProvider')
  }

  return context
}
